"""Regenerates src/PortableDocument.Content/Shaping/CanonicalComposition.cs (canonical base+mark pairs for Latin, Greek and Cyrillic).

    python generate_composition.py
"""
import os
import unicodedata

pairs = []
for c in range(0xC0, 0x2000):
    ch = chr(c)
    dec = unicodedata.decomposition(ch)
    if not dec or dec.startswith("<"):
        continue
    parts = [int(p, 16) for p in dec.split()]
    if len(parts) != 2 or not (0x300 <= parts[1] <= 0x36F):
        continue
    if unicodedata.normalize("NFC", chr(parts[0]) + chr(parts[1])) != ch:
        continue
    pairs.append((parts[0], parts[1], c))
pairs.sort()

here = os.path.dirname(os.path.abspath(__file__))
target = os.path.normpath(os.path.join(here, "..", "..", "..", "src", "PortableDocument.Content", "Shaping", "CanonicalComposition.cs"))
lines = []
row = []
for i, (b, m, c) in enumerate(pairs):
    row.append(f"0x{b:X}, 0x{m:X}, 0x{c:X}")
    if len(row) == 6:
        lines.append("        " + ", ".join(row) + ",")
        row = []
if row:
    lines.append("        " + ", ".join(row) + ",")

with open(target, "w", encoding="utf-8", newline="\n") as f:
    f.write("""namespace PortableDocument.Content.Shaping;

/// <summary>Canonical base + combining-mark compositions (generated by tests/fixtures/shaping/generate_composition.py from the Unicode database; Latin, Greek, Cyrillic and related blocks).</summary>
internal static class CanonicalComposition
{
    // (base, mark, composed) triples sorted by (base, mark).
    static readonly int[] Triples =
    [
""" + "\n".join(lines) + """
    ];

    static Dictionary<int, (int Base, int Mark)>? _inverse;

    public static bool TryCompose(int baseCp, int mark, out int composed)
    {
        int lo = 0, hi = Triples.Length / 3 - 1;
        while (lo <= hi)
        {
            var mid = (lo + hi) >> 1;
            var b = Triples[mid * 3]; var m = Triples[mid * 3 + 1];
            var cmp = b != baseCp ? b.CompareTo(baseCp) : m.CompareTo(mark);
            if (cmp == 0) { composed = Triples[mid * 3 + 2]; return true; }
            if (cmp < 0) lo = mid + 1; else hi = mid - 1;
        }
        composed = 0;
        return false;
    }

    public static bool TryDecompose(int composed, out int baseCp, out int mark)
    {
        var inv = _inverse;
        if (inv is null)
        {
            inv = new Dictionary<int, (int, int)>(Triples.Length / 3);
            for (var i = 0; i < Triples.Length; i += 3) inv[Triples[i + 2]] = (Triples[i], Triples[i + 1]);
            _inverse = inv;
        }
        if (inv.TryGetValue(composed, out var p)) { baseCp = p.Base; mark = p.Mark; return true; }
        baseCp = mark = 0;
        return false;
    }
}
""")
print("wrote", len(pairs), "pairs to", target)
